-- Replace the bundled sample catalog (fictional products, their demo installs, deployments and upgrade waves)
-- with real Microsoft energy solutions imported from their repositories. Customers, connections and landing
-- zones stay. Sample rows all use ids starting 22222222-.

-- Removing installs clears their references in the audit log (on delete set null), which the append-only
-- trigger would otherwise refuse. The events themselves stay.
alter table public.audit_events disable trigger audit_events_no_update;

delete from public.upgrade_waves
where offering_version_id in (
  select v.id from public.offering_versions v
  join public.offerings o on o.id = v.offering_id
  where o.product_id::text like '22222222-%'
);
delete from public.environments
where offering_id in (select id from public.offerings where product_id::text like '22222222-%');
delete from public.delivery_units where kind = 'solution' and product_id::text like '22222222-%';
delete from public.products where id::text like '22222222-%';

alter table public.audit_events enable trigger audit_events_no_update;

insert into public.audit_events (organization_id, actor_name, event_type, resource_type, resource_id, new_value, result, metadata_json)
select id, 'Cloud Delivery catalog', 'catalog.samples_removed', 'catalog', 'solution-catalog',
  '{"reason":"Bundled fictional samples replaced by real Microsoft energy solutions"}'::jsonb, 'success', '{}'::jsonb
from public.organizations where id = '11111111-1111-1111-1111-111111111111';

